const B1 = `linear-gradient(180deg, #fff, color-mix(in srgb, var(--acc) 45%, #fff))`;
const B2 = `linear-gradient(180deg, #fff, color-mix(in srgb, var(--acc2) 45%, #fff))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1, 150, 48)}top:60px;">AI AGENT<br><span style="font-size:30px;opacity:0.8">BUILD & VERIFY</span></div>
  <div id="c1" style="${STY(B2, 110, 42)}top:300px;">RUST LOGIC</div>
  <div id="c2" style="${STY(B1, 80, 32)}top:430px;width:500px;left:220px;z-index:2;">SECURE LAYER</div>
  <div id="c3" style="${STY(B2, 110, 42)}top:530px;">TYPESCRIPT UI</div>
  <div id="c4" style="${STY(B1, 130, 38)}top:730px;">WEB • macOS • iOS • LINUX</div>
  <div id="gh" style="position:absolute;bottom:60px;width:940px;text-align:center;color:#fff;font-size:36px;font-weight:800;opacity:0;">4,877 GITHUB STARS</div>
  <svg style="position:absolute;top:0;left:0;width:940px;height:1060px;fill:none;stroke:#fff;stroke-width:6;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 210 L470 300" />
    <path id="l1" d="M470 640 L470 730" />
  </svg>
`;

const items = [0, 1, 2, 3, 4].map(i => root.querySelector('#c' + i));
const stars = root.querySelector('#gh');
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Top Agent Card
  const s0 = spr(tf, 0, 0.85, 8);
  items[0].style.opacity = clamp(s0 * 2);
  items[0].style.transform = `translateY(${lerp(30, 0, E_OUT(clamp(s0)))}px) scale(${lerp(0.9, 1, E_OUT(clamp(s0)))})`;

  // Line 1
  const sl0 = spr(tf, 0.5, 0.9, 10);
  lines[0].el.style.strokeDashoffset = lines[0].len * (1 - clamp(sl0));

  // Architecture Stack
  [1, 2, 3].forEach((idx, i) => {
    const s = spr(tf, 0.8 + i * 0.15, 0.85, 8);
    items[idx].style.opacity = clamp(s * 2);
    items[idx].style.transform = `translateY(${lerp(20, 0, E_OUT(clamp(s)))}px) scale(${lerp(0.95, 1, E_OUT(clamp(s)))})`;
  });

  // Line 2
  const sl1 = spr(tf, 1.8, 0.9, 10);
  lines[1].el.style.strokeDashoffset = lines[1].len * (1 - clamp(sl1));

  // Cross-platform and Stars
  const s4 = spr(tf, 2.2, 0.85, 8);
  items[4].style.opacity = clamp(s4 * 2);
  items[4].style.transform = `translateY(${lerp(20, 0, E_OUT(clamp(s4)))}px)`;

  const ss = spr(tf, 2.7, 0.9, 8);
  stars.style.opacity = clamp(ss);
  stars.style.transform = `translateY(${lerp(15, 0, E_OUT(clamp(ss)))}px)`;
}
